# -*- coding: utf-8 -*-
"""KM 메뉴 수리기 — 49·50번이 메뉴에 안 보일 때 (2026-09-20)

하는 일
  1) 이 컴퓨터에서 KM 도구 폴더(menu.py 가 있는 곳)를 **전부** 찾습니다
  2) 그 폴더마다 도구 3개(t49·t50·sangun_card)가 있는지 보고, 없으면 넣습니다
  3) menu.py 에 49·50번이 없으면 넣습니다 (여러 모양에 대응)
  4) 무엇을 했는지 표로 보여 드립니다
바꾸는 파일은 .백업_260920 으로 남기고, 아무것도 지우지 않습니다.
"""
import base64
import io
import os
import datetime

STAMP = datetime.date.today().strftime('%y%m%d')
FILES = {
"km_tools/sangun_card.py": "",
"km_tools/t49_sangun.py": "",
"km_tools/t50_sangun_trace.py": ""
}

L49 = "   ('산군 관심현장 정리  산군 파일 → 새 현장만 판정·중복제거 (토큰 0)', 't49_sangun'),"
L50 = "   ('산군 흔적 찾기·메일  인터넷에서 찾아 빨리 갈 곳/물어볼 곳으로 갈라 메일 · 주1회 자동 (토큰 0)', 't50_sangun_trace')"

try:
    import sys
    sys.stdout.reconfigure(encoding='utf-8')
except Exception:
    pass


def find_menus():
    """menu.py 가 있는 폴더를 전부 찾는다."""
    out = []
    home = os.path.expanduser('~')
    roots = [os.path.join(home, 'OneDrive'), home]
    for d in ('C:\\', 'D:\\'):
        if os.path.isdir(d):
            roots.append(d)
    seen = set()
    for r in roots:
        if not os.path.isdir(r):
            continue
        for root, dirs, files in os.walk(r):
            depth = root.count(os.sep) - r.count(os.sep)
            if depth > 6:
                dirs[:] = []
                continue
            dirs[:] = [x for x in dirs if not x.startswith(('.', '$', 'AppData', 'Windows', 'Program'))]
            if 'menu.py' in files and 'common.py' in files:
                rp = os.path.realpath(root)
                if rp not in seen:
                    seen.add(rp)
                    out.append(root)
        if out:
            break
    return out


def backup(p):
    if not os.path.exists(p):
        return
    b = '%s.백업_%s' % (p, STAMP)
    n = 1
    while os.path.exists(b):
        b = '%s.백업_%s_%d' % (p, STAMP, n)
        n += 1
    io.open(b, 'wb').write(io.open(p, 'rb').read())


def put_tools(d):
    n = 0
    for rel, b64 in FILES.items():
        name = rel.split('/')[-1]
        p = os.path.join(d, name)
        old = io.open(p, 'rb').read() if os.path.exists(p) else b''
        new = base64.b64decode(b64)
        if old == new:
            continue
        backup(p)
        io.open(p, 'wb').write(new)
        n += 1
    return n


def fix_menu(d):
    p = os.path.join(d, 'menu.py')
    s = io.open(p, encoding='utf-8').read()
    if 't49_sangun' in s and 't50_sangun_trace' in s:
        return '이미 있음'
    # 붙일 자리를 여러 모양으로 찾는다
    for anchor, rep in (
        ("'t48_reply')]),", "'t48_reply'),\n%s\n%s]),"),
        ("'t48_reply') ]),", "'t48_reply'),\n%s\n%s]),"),
        ("'t47_visit')]),", "'t47_visit'),\n%s\n%s]),"),
    ):
        if anchor in s:
            backup(p)
            s = s.replace(anchor, rep % (L49, L50), 1)
            io.open(p, 'w', encoding='utf-8').write(s)
            return '넣었습니다'
    # 마지막 수단 : GROUPS 의 마지막 ']' 앞에 새 묶음을 통째로 붙인다
    i = s.rfind(']\n')
    if i > 0 and 'GROUPS' in s[:i]:
        backup(p)
        blk = " ('산군', [\n%s\n%s]),\n" % (L49, L50)
        s = s[:i] + blk + s[i:]
        io.open(p, 'w', encoding='utf-8').write(s)
        return '새 묶음으로 넣었습니다'
    return '못 넣었습니다 (이 창을 클로드에게 보여 주십시오)'


def main():
    print('=' * 62)
    print(' KM 메뉴 수리기 — 49·50번 넣기  (2026-09-20)')
    print('=' * 62)
    print('컴퓨터에서 KM 도구 폴더를 찾는 중입니다. 잠시만…')
    ds = find_menus()
    if not ds:
        print('[못 찾음] menu.py 가 있는 폴더를 못 찾았습니다.')
        print('  시작.bat 을 우클릭 > 속성 > 「대상」 에 적힌 경로를 알려 주십시오.')
        return
    print('')
    print('찾은 도구 폴더 %d곳' % len(ds))
    print('-' * 62)
    for d in ds:
        n = put_tools(d)
        r = fix_menu(d)
        has = all(os.path.exists(os.path.join(d, x.split('/')[-1])) for x in FILES)
        print('  %s' % d)
        print('     도구 파일 : %s%s' % ('3개 모두 있음' if has else '없음',
                                        ('  (%d개 새로 넣음)' % n) if n else ''))
        print('     메뉴 49·50 : %s' % r)
    print('-' * 62)
    print('')
    print('이제 시작(시작.bat 또는 시작.py)을 **닫았다가 다시 켜십시오.**')
    print('메뉴 맨 아래에 49·50번이 보이면 성공입니다.')
    print('')
    print('그래도 안 보이면 : 위 폴더로 들어가 t49_sangun.py 를 직접 더블클릭하셔도 됩니다.')


if __name__ == '__main__':
    try:
        main()
    except Exception as e:
        print('')
        print('[멈췄습니다] %s' % e)
        print('이 창을 캡처해서 클로드에게 보여 주십시오.')
    try:
        input('\n엔터를 누르면 닫힙니다...')
    except Exception:
        pass
